 const saveMcnSetup=async(draftOverride:any=null)=>{if(!accountId)return;const draft=draftOverride||mcnDraft;setMcnSaving(true);setNote('');try{const sourceIps=String(draft.source_ips||'').split(/[\s,;]+/).map((x:string)=>x.trim()).filter(Boolean);const number=String(draft.number||'').trim();const trunkPayload:any={account_id:accountId,provider:'mcn',name:String(draft.name||'MCN основной').trim()||'MCN основной',auth_mode:draft.auth_mode==='ip'?'ip':'registration',registrar:String(draft.registrar||'').trim(),outbound_proxy:String(draft.outbound_proxy||'').trim(),source_ips:sourceIps,codecs:['alaw'],dtmf_mode:'rfc4733',allowed_cli:number&&draft.outbound_cli_enabled!==false?[number]:[],enabled:true};if(String(draft.username||'').trim())trunkPayload.username=String(draft.username).trim();if(String(draft.password||'').trim())trunkPayload.password=String(draft.password);let tr:any=null;let verifiedByOnboard=false;if(number){const onboard=await apiPost('/api/mcn/onboard',{account_id:accountId,trunk:trunkPayload,did:{number,region:String(draft.region||'').trim(),purpose:'main',status:'active',inbound_enabled:true,outbound_cli_enabled:draft.outbound_cli_enabled!==false}});if(onboard?.status!=='ok'){setNote(onboard?.message||onboard?.detail||'Не удалось атомарно сохранить MCN: транк и номер не изменены');return;}tr={status:'ok',trunk:onboard?.trunk,pjsip_guardian:onboard?.pjsip_guardian};verifiedByOnboard=true;}else{tr=await apiPost('/api/mcn/trunks',trunkPayload);if(tr?.status!=='ok'){setNote(tr?.message||tr?.detail||'Не удалось сохранить SIP-транк MCN');return;}}await new Promise(r=>setTimeout(r,900));if(!verifiedByOnboard){try{await apiPost('/api/telephony/provider-config/verify',{account_id:accountId})}catch{}}const latest=await apiGet(`/api/mcn/setup?account_id=${encodeURIComponent(accountId)}`);setMcnSetup(latest);try{const pc=await apiGet(`/api/telephony/provider-config?account_id=${encodeURIComponent(accountId)}`);setProviderCfg(pc?.config||null)}catch{}const blockers=Array.isArray(latest?.readiness?.blockers)?latest.readiness.blockers:[];const deferred=tr?.pjsip_guardian?.deferred===true;setMcnDraft((v:any)=>({...v,username:'',password:''}));setNote(latest?.readiness?.ready?'MCN подключён: транк и номер подтверждены BORIS.':deferred?'Настройки MCN сохранены. Активный звонок не прерываем — BORIS применит SIP сам после освобождения линии.':blockers.includes('mcn_trunk_not_verified')?'Настройки сохранены. BORIS автоматически проверяет регистрацию SIP; владельцу ничего перезапускать не нужно.':blockers.includes('mcn_active_did_missing')?'Транк сохранён. Добавьте выданный MCN номер, чтобы включить входящие звонки.':'Настройки MCN сохранены. BORIS продолжает автоматическую проверку.');await load()}catch(e:any){setNote(e?.message||'Не удалось сохранить подключение MCN')}finally{setMcnSaving(false)}};
 const saveAndVerifyProvider=async()=>{if(!accountId||!providerDraft)return;setProviderSaving(true);setNote('');try{const cleanSecrets=Object.fromEntries(Object.entries(providerSecrets).filter(([,v])=>String(v||'').trim()));const body:any={account_id:accountId,provider:providerDraft,public_config:providerPublic};if(Object.keys(cleanSecrets).length)body.credentials=cleanSecrets;if(providerWebhookSecret.trim())body.webhook_secret=providerWebhookSecret.trim();const saved=await apiPost('/api/telephony/provider-config',body);if(saved?.status!=='ok'){setNote(saved?.message||'Не удалось сохранить подключение');return}const verified=await apiPost('/api/telephony/provider-config/verify',{account_id:accountId});setProviderCfg(saved?.config||null);setProviderSecrets({});const sip=verified?.sip_trunk;setNote(providerDraft==='telphin'?(verified?.connected&&Number(sip?.registered||0)>0?'API Телфин проверен. SIP-линия Registered — контур звука готов к реальному звонку.':verified?.connected?'API Телфин проверен. SIP: '+(sip?.apply?.status==='deferred'?'применится автоматически после активного звонка':Number(sip?.rejected||0)>0?'регистрация отклонена — проверьте Логин SIP/password':sip?.rendered?.configured?'ожидаем Registered':'SIP-линия ещё не настроена')+'.':Number(sip?.registered||0)>0?'SIP-линия Registered, но Проверка API-check не пройден. Проверьте client_id/client_secret.':verified?.message||'Настройки сохранены. API и SIP ещё не подтверждены.'):(verified?.connected?'Оператор проверен и подключён':verified?.status==='adapter_pending'?'Доступ сохранён. Рабочее подключение этого оператора ещё не готов.':verified?.status==='credentials_required'?'Настройки сохранены. Введите production API-ключи оператора.':verified?.message||'Доступ сохранён, но проверки состояния не пройден'));await load()}catch{setNote('Не удалось сохранить или проверить оператора')}finally{setProviderSaving(false)}};
 const verifyProvider=async()=>{if(!accountId)return;setProviderSaving(true);setNote('');try{const r=await apiPost('/api/telephony/provider-config/verify',{account_id:accountId});const sip=r?.sip_trunk;setNote(providerDraft==='telphin'?(r?.connected&&Number(sip?.registered||0)>0?'API и SIP Телфин подтверждены.':r?.connected?'API Телфин подтверждён. SIP: '+(sip?.apply?.status==='deferred'?'применится после текущего звонка':Number(sip?.rejected||0)>0?'Rejected — проверьте Логин SIP/password':sip?.rendered?.configured?'ожидаем Registered':'не настроен')+'.':r?.message||r?.status||'Проверка API-check не пройден'):(r?.connected?'Health-check пройден. Телефония подключена.':r?.message||r?.status||'Health-check не пройден'));await load()}catch{setNote('Не удалось выполнить проверки состояния')}finally{setProviderSaving(false)}};
 const saveRecordingPolicy=async()=>{if(!accountId)return;setRecordingSaving(true);setNote('');try{const body:any={account_id:accountId,policy:recordingCfg.policy,acknowledged:recordingCfg.policy==='not_required'?!!recordingCfg.acknowledged:false};const r=await apiPost('/api/telephony/recording/settings',body);if(r?.status==='acknowledgement_required'){setNote(r?.message||'Нужно подтверждение владельца');return}if(r?.status!=='ok'){setNote(r?.message||'Не удалось сохранить политику записи');return}setRecordingCfg({...r.settings,acknowledged:false});setNote(r.settings?.policy==='disabled'?'Запись новых звонков отключена.':r.settings?.policy==='not_required'?'Политика сохранена: новые звонки будут записываться автоматически по подтверждённому правилу аккаунта.':'Безопасный ручной режим сохранён: запись начнётся только после статуса уведомления/согласия.')}catch{setNote('Не удалось сохранить политику записи')}finally{setRecordingSaving(false)}};
 const saveAutoanswer=async()=>{setLoading(true);try{const a=await apiPost('/api/telephony/afterhours/settings',{account_id:accountId,...autoCfg,enabled:autoCfg.autoanswer_mode!=='off'});if(a?.settings)setAutoCfg(a.settings);const v=await apiPost('/api/telephony/voice-agent/settings',{account_id:accountId,...voiceCfg});if(v?.settings)setVoiceCfg(v.settings);const d=await apiGet(`/api/telephony/autoanswer/decision?account_id=${encodeURIComponent(accountId)}&ring_seconds=${Number(autoCfg.no_answer_seconds||25)}&human_available=false`);setAutoDecision(d);try{setAutoReady(await apiGet(`/api/telephony/autoanswer/readiness?account_id=${encodeURIComponent(accountId)}`));setAutoPreview(await apiGet(`/api/telephony/autoanswer/preview?account_id=${encodeURIComponent(accountId)}`))}catch{};setNote('Настройки автоответчика сохранены')}catch{setNote('Не удалось сохранить автоответчик')}finally{setLoading(false)}};
 return <main className="bp-wrap">
  <header className="bp-head"><div><span className="bp-kicker">BORIS · ТЕЛЕФОНИЯ</span><h1>Телефония</h1><p>Звонки, маршрутизация, CRM, записи и ИИ-разбор — единый контур.</p></div><div className={`bp-status ${data?.provider_state==='connected'?'ok':''}`}><i/>{statusText}</div></header>
  <section className="bp-grid4"><div className="bp-kpi"><span>Звонков · 30 дней</span><strong>{fmt(metrics.total)}</strong></div><div className="bp-kpi"><span>Принято</span><strong>{fmt(metrics.answered)}</strong></div><div className="bp-kpi"><span>Пропущено</span><strong>{fmt(metrics.missed)}</strong></div><div className="bp-kpi"><span>Просрочен обратный звонок</span><strong>{fmt(metrics.callback_overdue)}</strong></div></section>
  <nav className="bp-tabs">{['Звонки','Автоответчик','Маршрутизация','Записи','Устройства','Приложения','Аналитика','Минуты','Экономика','Подключение'].map(x=><button key={x} className={tab===x?'active':''} onClick={()=>setTab(x)}>{x}</button>)}</nav>
  {tab==='Звонки'&&<><section className="bp-main"><div className="bp-dialer"><div className="bp-panel-title"><span><Icon name="support" size={20}/></span><div><b>Позвонить</b><small>{provider}</small></div></div><input value={number} onChange={e=>setNumber(e.target.value)} placeholder="+7 999 123-45-67" inputMode="tel"/><button onClick={call}><Icon name="support" size={18}/> Позвонить</button>{note?<div className="bp-note">{humanizeBusinessText(note,'Состояние обновлено')}</div>:null}<div className="bp-provider"><b>Рабочее место менеджера</b><span>Web Phone</span><em>{data?.platforms?.web==='media_transport_ready'?'Медиа готово':data?.platforms?.web==='ui_ready_media_waiting_provider'?'Интерфейс и realtime готовы · ждём SIP/WebRTC':'—'}</em><span>CRM</span><em>Связана</em><span>Контроль пропущенных</span><em>Работает</em></div></div>
  <div className="bp-side"><div className="bp-panel-title"><span><Icon name="target" size={20}/></span><div><b>Управление звонком</b><small>{selected?selected.id:'Выберите звонок в истории'}</small></div></div>{selected?<><div className="bp-active-call"><b>{selected.direction==='inbound'?selected.from_number:selected.to_number}</b><span>{stateName[selected.state]||humanizeBusinessText(selected.state,'Состояние звонка уточняется')}</span></div><div className="bp-controls"><button onClick={()=>control('answer')}>Ответить</button><button onClick={()=>control('hold')}>Удержать</button><button onClick={()=>control('resume')}>Вернуть</button><button className="danger" onClick={()=>control('hangup')}>Завершить</button></div><small className="bp-truth">Команды не имитируют звонок: до подключения оператора они остаются в статусе ожидания.</small></>:<div className="bp-empty">Нажмите на звонок ниже.</div>}</div></section>
  <section className="bp-calls"><div className="bp-panel-title"><span><Icon name="chart" size={20}/></span><div><b>Последние звонки</b><small>Нажмите строку для управления</small></div></div>{calls.length?<div className="bp-table"><div className="bp-tr head"><span>Клиент</span><span>Направление</span><span>Статус</span><span>Разговор</span><span>Время</span></div>{calls.map((c:any)=><button className={`bp-tr bp-rowbtn ${selected?.id===c.id?'selected':''}`} key={c.id} onClick={()=>setSelected(c)}><span><b>{c.direction==='inbound'?c.from_number:c.to_number}</b><small>{humanizeBusinessText(c.source,'Телефония')}</small></span><span>{c.direction==='inbound'?'Входящий':'Исходящий'}</span><span>{stateName[c.state]||humanizeBusinessText(c.state,'Состояние звонка уточняется')}</span><span>{Math.round((c.talk_duration_sec||0)/60)} мин</span><span>{date(c.started_at)}</span></button>)}</div>:<div className="bp-empty">Реальных звонков через BORIS Phone пока нет. Данные не подменяются демонстрационными.</div>}</section></>}
  {tab==='Автоответчик'&&<section className="bp-autoanswer"><div className="bp-calls"><div className="bp-panel-title"><span><Icon name="ai" size={20}/></span><div><b>Умный автоответчик BORIS</b><small>Отвечает по вашему правилу, квалифицирует клиента и передаёт результат в CRM.</small></div></div>{autoReady?<div className={`bp-auto-ready ${autoReady.ready?'ready':autoReady.configured?'waiting':''}`}><div><span>{autoReady.ready?'✓':'✦'}</span><div><b>{autoReady.ready?'Автоответчик готов к реальным звонкам':autoReady.configured?'Настройки готовы · ждём внешний контур':'Автоответчик выключен'}</b><small>{autoReady.ready?'Политика, media, знания и пакет минут готовы.':autoReady.blockers?.includes('telephony_provider_not_verified')?'Оператор пока не подключён — настройки уже сохраняются и будут применены автоматически.':'Проверьте настройки ниже.'}</small></div></div><em>{autoReady.engine==='voice_agent'?'голосовой помощник':'Сценарный режим'} · {autoReady.remaining_minutes??0} мин</em></div>:null}<div className="bp-auto-modes">{[['off','Выключен','Никогда не отвечать автоматически','☎'],['afterhours','Вне рабочего времени','Только когда команда не работает','☾'],['no_answer','Если не ответили','Сначала менеджеры, потом BORIS','◷'],['always','Всегда','BORIS принимает каждый новый входящий','✦']].map(([k,t,d,i])=><button key={k} className={autoCfg.autoanswer_mode===k?'selected':''} onClick={()=>setAutoCfg({...autoCfg,autoanswer_mode:k,enabled:k!=='off'})}><i>{i}</i><b>{t}</b><span>{d}</span></button>)}</div><div className="bp-auto-grid"><div className="bp-auto-card"><b>Когда отвечать</b>{autoCfg.autoanswer_mode==='no_answer'?<label>Подключить BORIS через<input type="number" min="5" max="120" value={autoCfg.no_answer_seconds??25} onChange={e=>setAutoCfg({...autoCfg,no_answer_seconds:Number(e.target.value)})}/><small>секунд без ответа менеджера</small></label>:null}<div className="bp-schedule"><label>Работаем с<input type="time" value={autoCfg.work_start||'09:00'} onChange={e=>setAutoCfg({...autoCfg,work_start:e.target.value})}/></label><label>До<input type="time" value={autoCfg.work_end||'18:00'} onChange={e=>setAutoCfg({...autoCfg,work_end:e.target.value})}/></label></div><label>Часовой пояс<input value={autoCfg.timezone||'Europe/Moscow'} onChange={e=>setAutoCfg({...autoCfg,timezone:e.target.value})}/></label><label>Перезвон после нерабочего звонка, час<input type="number" min="0" max="23" value={autoCfg.callback_hour??9} onChange={e=>setAutoCfg({...autoCfg,callback_hour:Number(e.target.value)})}/><small>Если час вне рабочего окна, BORIS поставит задачу на начало рабочего дня.</small></label><div className="bp-days">{['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map((d,i)=><button key={d} className={(autoCfg.work_days||[]).includes(i)?'on':''} onClick={()=>{const a=new Set(autoCfg.work_days||[]);a.has(i)?a.delete(i):a.add(i);setAutoCfg({...autoCfg,work_days:[...a].sort()})}}>{d}</button>)}</div></div><div className="bp-auto-card"><b>Что говорит BORIS</b><label>Приветствие<textarea value={autoCfg.greeting||''} onChange={e=>setAutoCfg({...autoCfg,greeting:e.target.value})}/></label><label>Фраза про обратный звонок<textarea value={autoCfg.voicemail_text||''} onChange={e=>setAutoCfg({...autoCfg,voicemail_text:e.target.value})}/></label><label className="bp-switchrow"><span><b>Сообщать, что отвечает ИИ</b><small>Не маскировать виртуального помощника под человека</small></span><input type="checkbox" checked={voiceCfg.disclosure_required!==false} onChange={e=>setVoiceCfg({...voiceCfg,disclosure_required:e.target.checked})}/></label><label>Фраза о виртуальном помощнике<textarea value={voiceCfg.disclosure_text||'Здравствуйте! Вам отвечает виртуальный помощник BORIS.'} onChange={e=>setVoiceCfg({...voiceCfg,disclosure_text:e.target.value})}/><small>BORIS не будет повторять её, если приветствие уже явно сообщает, что отвечает AI.</small></label></div><div className="bp-auto-card"><b>Что собрать у клиента</b><label className="bp-switchrow"><span><b>Телефон</b><small>Повторить номер и получить подтверждение</small></span><input type="checkbox" checked={autoCfg.collect_phone!==false} onChange={e=>setAutoCfg({...autoCfg,collect_phone:e.target.checked})}/></label><label className="bp-switchrow"><span><b>Тема звонка</b><small>Кратко понять, что нужно клиенту</small></span><input type="checkbox" checked={autoCfg.collect_topic!==false} onChange={e=>setAutoCfg({...autoCfg,collect_topic:e.target.checked})}/></label><label className="bp-switchrow"><span><b>Создать задачу в CRM</b><small>Менеджер получает готовую задачу на перезвон</small></span><input type="checkbox" checked={autoCfg.create_crm_task!==false} onChange={e=>setAutoCfg({...autoCfg,create_crm_task:e.target.checked})}/></label></div><div className="bp-auto-card"><b>Умный голосовой помощник</b><label className="bp-switchrow"><span><b>Включить ИИ-диалог</b><small>Если выключено — безопасный сценарный автоответчик</small></span><input type="checkbox" checked={!!voiceCfg.enabled} onChange={e=>setVoiceCfg({...voiceCfg,enabled:e.target.checked})}/></label><label>Максимальная длительность ИИ-разговора, мин<input type="number" min="1" max="60" value={voiceCfg.max_call_minutes??15} onChange={e=>setVoiceCfg({...voiceCfg,max_call_minutes:Number(e.target.value)})}/></label><label className="bp-switchrow"><span><b>Передавать неизвестный вопрос менеджеру</b><small>Не придумывать ответ, если факта нет в базе компании</small></span><input type="checkbox" checked={voiceCfg.handoff_on_unknown!==false} onChange={e=>setVoiceCfg({...voiceCfg,handoff_on_unknown:e.target.checked})}/></label><label className="bp-switchrow"><span><b>Можно называть цены</b><small>Только подтверждённые факты компании</small></span><input type="checkbox" checked={!!voiceCfg.allow_prices} onChange={e=>setVoiceCfg({...voiceCfg,allow_prices:e.target.checked})}/></label><label className="bp-switchrow"><span><b>Можно давать обязательства</b><small>По умолчанию запрещено</small></span><input type="checkbox" checked={!!voiceCfg.allow_commitments} onChange={e=>setVoiceCfg({...voiceCfg,allow_commitments:e.target.checked})}/></label></div></div>{autoPreview?.steps?.length?<div className="bp-auto-preview"><div className="bp-panel-title"><span>▶</span><div><b>Как пройдёт звонок</b><small>Предпросмотр политики — без выдуманного звонка и без списания минут</small></div></div><div className="bp-auto-steps">{autoPreview.steps.map((x:any,i:number)=><div key={x.key}><i>{i+1}</i><span><b>{x.title}</b><small>{x.say}</small></span></div>)}</div></div>:null}<div className="bp-auto-facts"><div><small>Перехвачено · 30 дней</small><b>{autoAnalytics?.summary?.requested??0}</b></div><div><small>Обработано ИИ / сценарный режим</small><b>{autoAnalytics?.summary?.ai_handled??0}</b></div><div><small>Подтверждено телефонов</small><b>{autoAnalytics?.capture?.confirmed_phones??autoAnalytics?.sessions?.confirmed_phones??0}</b></div><div><small>Задач CRM</small><b>{autoAnalytics?.capture?.crm_tasks??autoAnalytics?.sessions?.crm_tasks??0}</b></div></div>{autoAnalytics?.recent?.length?<div className="bp-auto-recent"><b>Последние звонки автоответчика</b>{autoAnalytics.recent.slice(0,5).map((x:any)=><div key={x.id}><span><strong>{x.from_number||'Неизвестный номер'}</strong><small>{date(x.started_at)} · {humanizeBusinessText(x.autoanswer_reason||x.agent_mode,'Автоответчик')}</small></span><em>{x.crm_task_id?'CRM задача создана':humanizeBusinessText(x.session_state||x.state,'Состояние уточняется')}</em></div>)}</div>:null}<div className="bp-auto-actions"><button className="bp-primary" onClick={saveAutoanswer}>Сохранить автоответчик</button><button onClick={async()=>{try{setAutoDecision(await apiGet(`/api/telephony/autoanswer/decision?account_id=${encodeURIComponent(accountId)}&ring_seconds=${Number(autoCfg.no_answer_seconds||25)}&human_available=false`))}catch{}}}>Проверить правило</button></div>{autoDecision?<div className={`bp-auto-decision ${autoDecision.should_answer?'on':''}`}><b>{autoDecision.should_answer?'BORIS ответит':'BORIS не перехватит звонок'}</b><span>Режим: {humanizeBusinessText(autoDecision.mode,'автоматический')} · причина: {humanizeBusinessText(autoDecision.reason,'по правилам автоответчика')} · движок: {humanizeBusinessText(autoDecision.engine,'голосовой помощник')}</span>{autoDecision.opening_text?<small>Первое сообщение клиенту: «{autoDecision.opening_text}»</small>:null}</div>:null}{note?<div className="bp-note">{note}</div>:null}<small className="bp-truth">Даже в режиме «Всегда» BORIS не забирает звонок, который уже закреплён за реальным менеджером. До подключения оператора настройки сохраняются и проверяются, но не имитируют реальный аудиозвонок.</small></div></section>}
  {tab==='Маршрутизация'&&<section className="bp-route-grid"><div className="bp-side"><div className="bp-panel-title"><span><Icon name="target" size={20}/></span><div><b>Новый маршрут</b><small>Куда направлять входящие звонки</small></div></div><label>Название<input value={route.name} onChange={e=>setRoute({...route,name:e.target.value})}/></label><label>Куда звонить<select value={route.destination_kind} onChange={e=>setRoute({...route,destination_kind:e.target.value,destination_value:e.target.value==='device'?'all_online':''})}><option value="device">Все доступные устройства BORIS</option><option value="user">Конкретный менеджер</option><option value="group">Вся доступная команда</option><option value="sip">SIP-номер</option></select></label>{route.destination_kind!=='device'?<label>{route.destination_kind==='user'?'ID менеджера':route.destination_kind==='group'?'Команда':'SIP-назначение'}<input value={route.destination_value||''} onChange={e=>setRoute({...route,destination_value:e.target.value})}/></label>:null}<div className="bp-schedule"><label>С<input type="time" value={route.schedule?.start||'09:00'} onChange={e=>setRoute({...route,schedule:{...route.schedule,start:e.target.value}})}/></label><label>До<input type="time" value={route.schedule?.end||'21:00'} onChange={e=>setRoute({...route,schedule:{...route.schedule,end:e.target.value}})}/></label></div><label>Часовой пояс<input value={route.schedule?.timezone||'Europe/Moscow'} onChange={e=>setRoute({...route,schedule:{...route.schedule,timezone:e.target.value}})}/></label><label>Как распределять<select value={route.strategy||'ring_all'} onChange={e=>setRoute({...route,strategy:e.target.value})}><option value="ring_all">Звонить всем доступным</option><option value="round_robin">По очереди</option><option value="least_busy">Наименее занятому</option></select></label><label>Таймаут ответа, сек.<input type="number" min="5" max="120" value={route.ring_timeout_sec} onChange={e=>setRoute({...route,ring_timeout_sec:Number(e.target.value)})}/></label><label>Если не ответили<select value={route.fallback_kind||''} onChange={e=>setRoute({...route,fallback_kind:e.target.value})}><option value="voicemail">Голосовая почта</option><option value="callback">Создать задачу перезвонить</option><option value="group">Вся доступная команда</option></select></label><button className="bp-primary" onClick={saveRoute}>Сохранить маршрут</button>{note?<div className="bp-note">{note}</div>:null}</div><div className="bp-calls"><div className="bp-panel-title"><span><Icon name="list" size={20}/></span><div><b>Правила маршрутизации</b><small>По приоритету</small></div></div>{routes.length?routes.map((r:any)=><div className="bp-route" key={r.id}><div><b>{r.name}</b><small>{r.source||'Все источники'} · {r.ring_timeout_sec} сек. · {r.schedule_json?.start||'всегда'}–{r.schedule_json?.end||''}</small></div><span>{r.strategy==='round_robin'?'По очереди':r.strategy==='least_busy'?'Наименее занятому':'Всем'} · {r.destination_kind} → {r.destination_value||'автоматически'}</span></div>):<div className="bp-empty">Пока действует безопасный маршрут по умолчанию: все онлайн-устройства, 25 секунд.</div>}</div></section>}
  {tab==='Записи'&&<section className="bp-calls"><div className="bp-panel-title"><span><Icon name="memory" size={20}/></span><div><b>Записи и ИИ-разбор</b><small>Политика задаётся один раз; дальше BORIS применяет её к новым звонкам автоматически</small></div></div><div className="bp-econ-card bp-econ-wide"><b>Политика записи новых звонков</b><label>Режим<select value={recordingCfg.policy||'manual'} onChange={e=>setRecordingCfg({...recordingCfg,policy:e.target.value,acknowledged:false})}><option value="manual">Ручной / безопасный — ждать уведомления или согласия</option><option value="disabled">Не записывать звонки</option><option value="not_required">Записывать автоматически по политике компании</option></select></label>{recordingCfg.policy==='not_required'?<label className="bp-switchrow"><span><b>Подтверждаю правило аккаунта</b><small>Я подтверждаю, что для этих звонков у компании есть основание использовать этот режим. BORIS не определяет это самостоятельно.</small></span><input type="checkbox" checked={!!recordingCfg.acknowledged} onChange={e=>setRecordingCfg({...recordingCfg,acknowledged:e.target.checked})}/></label>:null}<button className="bp-primary" disabled={recordingSaving||recordingCfg.policy==='not_required'&&!recordingCfg.acknowledged} onClick={saveRecordingPolicy}>{recordingSaving?'Сохраняю…':'Сохранить политику записи'}</button><small>Изменение применяется к новым звонкам. Текущий разговор BORIS не переключает посреди звонка.</small></div>{recordings.length?recordings.map((r:any)=><div className="bp-record" key={r.id}><div><b>Звонок {r.call_id}</b><small>{date(r.created_at)} · {humanizeBusinessText(r.provider,'оператор')}</small></div><span>Запись: {humanizeBusinessText(r.status,'Состояние уточняется')}</span><span>Текст: {humanizeBusinessText(r.transcript_status,'Состояние уточняется')}</span><span>ИИ-разбор: {humanizeBusinessText(r.analysis_status,'Состояние уточняется')}</span></div>):<div className="bp-empty">Записей пока нет. Для Telphin/MCN запись через Asterisk попадёт сюда автоматически после разрешённого старта записи.</div>}{note?<div className="bp-note">{note}</div>:null}</section>}
  {tab==='Устройства'&&<section className="bp-calls"><div className="bp-panel-title"><span><Icon name="clients" size={20}/></span><div><b>Устройства менеджеров</b><small>Отключённое устройство не сможет зарегистрироваться повторно с тем же ID.</small></div></div>{devices.length?devices.map((d:any)=><div className="bp-device" key={d.id}><div><b>{d.name}</b><small>{d.platform} · {d.app_version||'web'} · {d.presence||'offline'} · {date(d.last_seen_at)} · Push: {d.push_ready?(d.push_kind||'подключён'):'не подключён'}</small></div><div className="bp-device-actions"><label className="bp-extension"><small>Добавочный</small><input defaultValue={d?.capabilities_json?.extension||''} inputMode="numeric" placeholder="101" maxLength={16} disabled={!!d.revoked_at} onBlur={async e=>{const ext=e.target.value.replace(/[^0-9*#]/g,'').slice(0,16);e.target.value=ext;const r=await apiPost(`/api/telephony/devices/${d.id}/extension`,{account_id:accountId,extension:ext});setNote(r?.status==='ok'?`Добавочный ${ext||'очищен'} для ${d.name}`:(r?.message||'Не удалось сохранить добавочный'));if(r?.status==='ok')await load()}}/></label><span className={d.online?'online':''}>{d.revoked_at?'Отключено':d.online?'Онлайн':'Офлайн'}</span>{!d.revoked_at?<button title="Только владелец может отозвать устройство" onClick={async()=>{const r=await apiPost(`/api/telephony/devices/${d.id}/revoke`,{account_id:accountId});if(r?.status==='ok'){setNote(`Устройство ${d.name} отключено`);await load()}else setNote(r?.message||'Отключить устройство может только владелец')}}>Отключить</button>:null}</div></div>):<div className="bp-empty">Устройства появятся после регистрации клиента.</div>}</section>}

  {tab==='Приложения'&&<section className="bp-calls"><div className="bp-panel-title"><span><Icon name="ai" size={20}/></span><div><b>Приложения BORIS Phone</b><small>Веб-приложение уже доступно; приложения для устройств показываются только по фактической готовности</small></div></div>{clientReadiness?<><div className="bp-minute-grid"><div><small>Готовность приложения</small><b>{clientReadiness.readiness_pct??0}%</b></div><div><small>Боевые звонки</small><b>{clientReadiness.telephony_readiness_pct??0}%</b></div><div><small>Веб-приложение</small><b>{clientReadiness.pwa_distribution_ready?'Готово':'Не готово'}</b></div><div><small>Оператор</small><b>{clientReadiness.telephony_gates?.provider_connected?'Подключён':'Не подключён'}</b></div><div><small>Реальная передача звука</small><b>{clientReadiness.telephony_gates?.real_media_provider?'Подтверждён':'Не подтверждён'}</b></div><div><small>Уведомления телефона</small><b>{clientReadiness.telephony_gates?.native_push_registered?'Есть':'Нет'}</b></div><div><small>Windows NSIS</small><b>{clientReadiness.build_evidence?.windows_unsigned_nsis?.built?'Собран':'Нет'}</b></div><div><small>Android AAB</small><b>{clientReadiness.build_evidence?.android_release_aab?.built?'Собран':'Нет'}</b></div><div><small>Проверка исходного кода iOS</small><b>{clientReadiness.build_evidence?.ios_source_release_contract?.validated?'Проверен':'Нет'}</b></div><div><small>Проверка целостности сборки</small><b>{clientReadiness.release_integrity?.status==='ok'?`${clientReadiness.release_integrity.sha256_verified_entries}/${clientReadiness.release_integrity.artifacts} SHA-256`:'Нет'}</b></div></div><div className="bp-econ-card bp-econ-wide"><b>Боевой контур звонков</b><span>Реальные звонки провайдера <strong>{clientReadiness.runtime_evidence?.calls?.provider_calls??0}</strong></span><span>Входящие / исходящие <strong>{clientReadiness.runtime_evidence?.calls?.provider_inbound??0} / {clientReadiness.runtime_evidence?.calls?.provider_outbound??0}</strong></span><span>Записи / расшифровки / ИИ-разборы <strong>{clientReadiness.runtime_evidence?.recordings?.recordings??0} / {clientReadiness.runtime_evidence?.recordings?.transcripts??0} / {clientReadiness.runtime_evidence?.recordings?.analyzed??0}</strong></span><span>Устройства онлайн <strong>{clientReadiness.runtime_evidence?.online_devices??0}</strong></span>{clientReadiness.primary_next_action?<div className="bp-note"><b>Что сейчас делать: </b>{clientReadiness.primary_next_action.text}<br/><small>Исполнитель: {clientReadiness.primary_next_action.actor==='boris'?'BORIS сам':clientReadiness.primary_next_action.actor==='manager'?'менеджер':clientReadiness.primary_next_action.actor==='owner'?'владелец':'ничего — готово'}</small></div>:null}<small>{clientReadiness.telephony_remaining_human?.length?`До полного E2E: ${clientReadiness.telephony_remaining_human.join(' · ')}`:'Полный телефонный E2E подтверждён.'}</small></div><div className="bp-econ-card bp-econ-wide"><b>Передача звука</b><span>Текущий оператор <strong>{clientReadiness.media_diagnostics?.provider||'не выбран'}</strong></span><span>Поддержка передачи звука адаптером <strong>{clientReadiness.media_diagnostics?.adapter_media_contract?'есть':'не реализован'}</strong></span><span>Модуль передачи звука BORIS <strong>{clientReadiness.media_diagnostics?.local_media_gateway_tools?.length?clientReadiness.media_diagnostics.local_media_gateway_tools.join(', '):'не обнаружен'}</strong></span><span>Реальная звуковая сессия <strong>{clientReadiness.media_diagnostics?.media_session_proven?'подтверждена':'не подтверждена'}</strong></span><small>{clientReadiness.media_diagnostics?.blockers_human?.length?`Почему ещё не готово: ${clientReadiness.media_diagnostics.blockers_human.join(' · ')}`:'Передача звука реального звонка полностью подтверждена.'}</small></div><div className="bp-econ-compare">{['windows','macos','android','ios'].map((k:string)=>{const x=clientReadiness.distribution?.[k]||{};return <div className="bp-econ-card" key={k}><b>{k==='windows'?'Windows':k==='macos'?'macOS':k==='android'?'Android':'iPhone / iPad'}</b><span>PWA <strong>{x.pwa_ready?'готова':'—'}</strong></span><span>Приложение для устройства <strong>{x.native_release_ready?'готов':'ещё нет'}</strong></span><small>{clientReadiness.release_blockers?.[k]}</small></div>})}</div><div className="bp-econ-card bp-econ-wide"><b>Проверенные артефакты</b><span>Проверенная сборка Windows <strong>{clientReadiness.build_evidence?.windows_unsigned_nsis?.sha256?clientReadiness.build_evidence.windows_unsigned_nsis.sha256.slice(0,12)+'…':'—'}</strong></span><span>Тестовая сборка Android <strong>{clientReadiness.build_evidence?.android_debug_apk?.sha256?clientReadiness.build_evidence.android_debug_apk.sha256.slice(0,12)+'…':'—'}</strong></span><span>Сборка Android для магазина <strong>{clientReadiness.build_evidence?.android_release_aab?.sha256?clientReadiness.build_evidence.android_release_aab.sha256.slice(0,12)+'…':'—'}</strong></span><small>SHA-256 подтверждает целостность файла, но не заменяет подпись приложения, проверку платформой и проверку качества на реальном устройстве.</small></div><div className="bp-econ-card bp-econ-wide"><b>Готовность уведомлений</b><span>iOS токенов <strong>{clientReadiness.push_health?.tokens?.ios_apns_voip??0}</strong></span><span>Android FCM токенов <strong>{clientReadiness.push_health?.tokens?.android_fcm??0}</strong></span><span>Доступ Apple к уведомлениям <strong>{clientReadiness.push_health?.credentials_configured?.apns?'настроены':'не настроены'}</strong></span><span>Доступ Android к уведомлениям <strong>{clientReadiness.push_health?.credentials_configured?.fcm?'настроены':'не настроены'}</strong></span><span>Принято APNs/FCM <strong>{clientReadiness.runtime_evidence?.native_push_provider_accepted??0}</strong></span><span>Подтверждено приложением <strong>{clientReadiness.runtime_evidence?.native_push_device_received??0}</strong></span><small>Успешный ответ службы уведомлений означает только приём сообщения. Доставка считается подтверждённой только после ответа BORIS Phone с конкретного устройства.</small></div></>:<div className="bp-empty">Загружаем фактическую готовность клиентов BORIS Phone…</div>}</section>}
  {tab==='Аналитика'&&<section className="bp-analytics"><div className="bp-calls"><div className="bp-panel-title"><span><Icon name="chart" size={20}/></span><div><b>Источники звонков</b><small>30 дней · только реальные данные</small></div></div>{analytics?.sources?.length?analytics.sources.map((x:any)=><div className="bp-analytic-row" key={x.source}><b>{humanizeBusinessText(x.source,'Источник')}</b><span>{x.calls} звонков</span><span>{x.answered} принято</span><span>{x.missed} пропущено</span><span>{x.with_deal} со сделкой</span></div>):<div className="bp-empty">Пока недостаточно звонков для аналитики.</div>}</div><div className="bp-calls"><div className="bp-panel-title"><span><Icon name="clients" size={20}/></span><div><b>Рабочие места</b><small>Менеджеры и устройства</small></div></div>{analytics?.managers?.length?analytics.managers.map((x:any,i:number)=><div className="bp-analytic-row" key={`${x.device_id||'none'}-${i}`}><b>{x.device_name||'Не назначено'}</b><span>{x.calls} звонков</span><span>{x.answered} принято</span><span>{Math.round((x.talk_seconds||0)/60)} мин разговора</span><span>{x.with_deal} сделок</span></div>):<div className="bp-empty">Данные появятся после звонков.</div>}<div className="bp-quality-head"><b>Качество разговоров</b><span>Проверено: {quality?.summary?.reviewed||0} · Средний балл: {quality?.summary?.avg_score||'—'}</span></div><div className="bp-rop-summary"><div><small>Требуют внимания</small><b>{quality?.attention?.length||0}</b></div><div><small>Сильные звонки</small><b>{quality?.summary?.strong||0}</b></div><div><small>Ниже 50</small><b>{quality?.summary?.needs_attention||0}</b></div></div>{quality?.skill_gaps?.length?<div className="bp-skill-gaps"><b>Повторяющиеся слабые навыки</b>{quality.skill_gaps.slice(0,4).map((g:any)=><div key={g.key}><span>{g.label}</span><em>{g.avg_score}/100 · слабых звонков {g.weak_calls}</em></div>)}</div>:null}{quality?.repeated_manager_gaps?.length?<div className="bp-repeat-gaps"><b>Повторяющиеся ошибки реальных менеджеров</b><small>Считаем по пользователю BORIS, а не по устройству</small>{quality.repeated_manager_gaps.slice(0,8).map((m:any)=><div key={m.manager_user_id}><span><strong>{m.manager_name}</strong><small>Проверено звонков: {m.reviewed}</small></span><em>{[['Потребность',m.weak_need],['Срок',m.weak_timeline],['Бюджет',m.weak_budget],['Презентация',m.weak_presentation],['Возражения',m.weak_objection],['След. шаг',m.weak_next]].filter((x:any)=>x[1]>0).map((x:any)=>`${x[0]} ×${x[1]}`).join(' · ')||'Повторяющихся критичных ошибок нет'}</em></div>)}</div>:null}{quality?.attention?.length?<div className="bp-attention"><b>Очередь внимания РОПа</b>{quality.attention.slice(0,8).map((x:any)=><div key={x.call_id}><span><strong>{x.device_name||'Менеджер'}</strong><small>{date(x.started_at)} · {x.from_number||x.to_number||'Звонок'}</small></span><em>{x.total_score}/100</em></div>)}</div>:null}{quality?.managers?.length?quality.managers.map((m:any,i:number)=><div className="bp-analytic-row" key={`quality-${i}`}><b>{m.manager_name||'Менеджер'}</b><span>{m.avg_score||0}/100</span><span>Потребность {m.need_score||0}</span><span>Срок {m.timeline_score||0}</span><span>След. шаг {m.next_step_score||0}</span></div>):<div className="bp-empty">Оценки появятся после реальных разговоров или транскрипций.</div>}<div className="bp-coaching"><div className="bp-panel-title"><span><Icon name="ai" size={20}/></span><div><b>Индивидуальные тренировки</b><small>Для реальных сотрудников: формируются автоматически из их разговоров с клиентами</small></div></div>{coaching.length?coaching.slice(0,8).map((x:any)=><div className="bp-coach-row" key={x.id}><div><b>{x.skill_label}</b><small>{x.manager_name||'Менеджер'} · исходный навык {x.baseline_score}/100</small><p>{x.training_goal}</p></div><a href={`/dashboard/ai?account_id=${encodeURIComponent(accountId)}`}>Открыть спарринг</a></div>):<div className="bp-empty">Сейчас нет критичных навыков, требующих отдельной тренировки.</div>}</div><div className="bp-report-settings"><div className="bp-panel-title"><span><Icon name="chart" size={20}/></span><div><b>Автоотчёты руководителю</b><small>Один раз настраиваем получателей — дальше BORIS отправляет отчёты сам</small></div></div><div className="bp-report-grid"><label>Email руководителя<input value={reportCfg.email_to||''} placeholder="director@company.ru" onChange={e=>setReportCfg({...reportCfg,email_to:e.target.value})}/></label><label>Telegram группа / chat ID<input value={reportCfg.telegram_chat_id||''} placeholder="-100…" onChange={e=>setReportCfg({...reportCfg,telegram_chat_id:e.target.value})}/></label><label>Тема Telegram (необязательно)<input value={reportCfg.telegram_thread_id||''} placeholder="ID темы" onChange={e=>setReportCfg({...reportCfg,telegram_thread_id:e.target.value})}/></label><label>Периодичность<select value={reportCfg.frequency||'daily'} onChange={e=>setReportCfg({...reportCfg,frequency:e.target.value})}><option value="daily">Каждый день</option><option value="weekly">Раз в неделю</option></select></label><label>Час отправки<input type="number" min="0" max="23" value={reportCfg.send_hour??9} onChange={e=>setReportCfg({...reportCfg,send_hour:Number(e.target.value)})}/></label><label>Часовой пояс<input value={reportCfg.timezone||'Europe/Moscow'} onChange={e=>setReportCfg({...reportCfg,timezone:e.target.value})}/></label></div><div className="bp-report-actions"><label><input type="checkbox" checked={!!reportCfg.enabled} onChange={e=>setReportCfg({...reportCfg,enabled:e.target.checked})}/> Автоматическая отправка включена</label><label><input type="checkbox" checked={!!reportCfg.minute_alerts_enabled} onChange={e=>setReportCfg({...reportCfg,minute_alerts_enabled:e.target.checked})}/> Предупреждать о 80/90/100% пакета минут</label><button className="bp-primary" onClick={async()=>{const r=await apiPost('/api/telephony/reports/settings',{account_id:accountId,...reportCfg});setNote(r?.status==='ok'?'Настройки автоотчётов сохранены':'Не удалось сохранить')}}>Сохранить</button><button onClick={async()=>{const r=await apiGet(`/api/telephony/reports/preview?account_id=${encodeURIComponent(accountId)}&days=${reportCfg.frequency==='weekly'?7:1}`);setNote(r?.text||'Предпросмотр недоступен')}}>Предпросмотр</button></div></div><div className="bp-analytics-foot"><span>Перезвонить: {analytics?.callbacks?.required||0}</span><span>Выполнено: {analytics?.callbacks?.completed||0}</span><span>Просрочено: {analytics?.callbacks?.overdue||0}</span><b>Себестоимость: {Number(analytics?.summary?.cost_rub||0).toFixed(2)} ₽</b></div></div></section>}
  {tab==='Минуты'&&<section className="bp-calls"><div className="bp-panel-title"><span><Icon name="chart" size={20}/></span><div><b>Пакет звонков</b><small>Включено, использовано и остаток. Внутренняя себестоимость здесь не показывается.</small></div></div><div className="bp-minute-grid"><div><small>Включено</small><b>{billing?.usage?.package_minutes??'—'} мин</b></div><div><small>Использовано</small><b>{billing?.usage?.used_minutes??'—'} мин</b></div><div><small>Осталось</small><b>{billing?.usage?.remaining_minutes??'—'} мин</b></div><div><small>Прогноз</small><b>{billing?.forecast?.projected_cycle_minutes??'—'} мин</b></div><div><small>Использовано пакета</small><b>{billing?.usage?.usage_percent??0}%</b></div></div>{billing?.alerts?.[0]?<div className="bp-note">Лимит: использовано {billing.alerts[0].usage_percent}% · предупреждение {billing.alerts[0].threshold}%</div>:null}<div className="bp-truth">В пакет входят звонки, контроль РОПа, ИИ-подсказки, обработка звонка и голосовой помощник в подключённых режимах. BORIS заранее предупредит о приближении к лимиту.</div></section>}
  {tab==='Экономика'&&<section className="bp-calls"><div className="bp-panel-title"><span><Icon name="chart" size={20}/></span><div><b>Экономика телефонии · владелец</b><small>Внутренняя себестоимость, CRM-конверсия и готовность данных для будущих тарифов</small></div></div><div className="bp-econ-actions">{[30,60,90].map(d=><button key={d} className={econDays===d?'active':''} onClick={async()=>{setEconDays(d);try{{const r=await apiGet(`/api/telephony/owner/economics?account_id=${encodeURIComponent(accountId)}&days=${d}`);setOwnerEconomics(r?.economics||r)}}catch{setOwnerEconomics({status:'forbidden'})}}}>{d} дней</button>)}<button className="bp-primary" onClick={async()=>{try{{const r=await apiGet(`/api/telephony/owner/economics?account_id=${encodeURIComponent(accountId)}&days=${econDays}`);setOwnerEconomics(r?.economics||r);try{setOwnerDashboard(await apiGet(`/api/telephony/owner/dashboard?account_id=${encodeURIComponent(accountId)}`))}catch{}}}catch{setOwnerEconomics({status:'forbidden'})}}}>Обновить</button></div>{!ownerEconomics?<div className="bp-empty">Нажмите «Обновить». Этот раздел доступен только владельцу и не раскрывает себестоимость клиентам.</div>:ownerEconomics.status==='forbidden'?<div className="bp-empty">Нет доступа к внутренней экономике.</div>:<><div className="bp-minute-grid"><div><small>CRM-атрибуция</small><b>{ownerEconomics.commercial_readiness?.crm_attribution_pct??0}%</b></div><div><small>Учтённая себестоимость</small><b>{ownerEconomics.commercial_readiness?.cost_attribution_pct??0}%</b></div><div><small>Данных для цены</small><b>{ownerEconomics.commercial_readiness?.pricing_ready?'Достаточно':'Пока мало'}</b></div><div><small>Закрытые CRM-исходы</small><b>{ownerEconomics.commercial_readiness?.closed_outcome_pct==null?'—':ownerEconomics.commercial_readiness.closed_outcome_pct+'%'}</b></div></div><div className="bp-econ-compare">{[['ИИ-помощник',ownerEconomics.outcome_economics?.voice_agent],['Менеджеры',ownerEconomics.outcome_economics?.human]].map(([name,x]:any)=><div className="bp-econ-card" key={name}><b>{name}</b><span>Звонков <strong>{x?.calls??0}</strong></span><span>CRM-сделок <strong>{x?.crm_deals??0}</strong></span><span>горячих лидов <strong>{x?.hot??0}</strong></span><span>Обратных звонков с ответом <strong>{x?.callbacks_answered??0}</strong></span><span>Продаж <strong>{x?.won_deals??0}</strong></span><span>Выручка выигранных сделок <strong>{Number(x?.won_revenue_rub||0).toLocaleString('ru-RU')} ₽</strong></span><span>Учтённая себестоимость <strong>{x?.tracked_cogs_rub==null?'—':Number(x.tracked_cogs_rub).toFixed(2)+' ₽'}</strong></span><span>Себестоимость / горячий лид <strong>{x?.cost_per_hot_rub==null?'—':Number(x.cost_per_hot_rub).toFixed(2)+' ₽'}</strong></span><span>Себестоимость / обратный звонок <strong>{x?.cost_per_callback_rub==null?'—':Number(x.cost_per_callback_rub).toFixed(2)+' ₽'}</strong></span><span>Себестоимость / продажа <strong>{x?.cost_per_won_rub==null?'—':Number(x.cost_per_won_rub).toFixed(2)+' ₽'}</strong></span></div>)}</div><div className="bp-econ-card bp-econ-wide"><b>Срок обратного звонка</b><span>Дозвонились <strong>{ownerEconomics.callback_funnel?.answered_callbacks??0}</strong></span><span>В срок <strong>{ownerEconomics.callback_funnel?.sla_rate_pct==null?'—':ownerEconomics.callback_funnel.sla_rate_pct+'%'}</strong></span><span>Просрочено <strong>{ownerEconomics.callback_funnel?.overdue_callbacks??0}</strong></span></div>{!ownerEconomics.commercial_readiness?.pricing_ready&&ownerEconomics.commercial_readiness?.blockers?.length?<div className="bp-readiness"><b>Почему тарифы пока нельзя считать по этим данным</b>{ownerEconomics.commercial_readiness.blockers.map((x:string)=><span key={x}>{humanizeBusinessText(x,'Нужно накопить или подключить данные')}</span>)}</div>:null}{ownerDashboard?.windows?.[String(econDays)]?<><div className="bp-econ-card bp-econ-wide"><b>Рекомендация по минутам</b><span>Прогноз за цикл <strong>{ownerDashboard.windows[String(econDays)].package?.projected_minutes??0} мин</strong></span><span>Рекомендуемый пакет <strong>{ownerDashboard.windows[String(econDays)].package?.recommended_package_minutes??300} мин</strong></span><span>Коммерческий статус <strong>{ownerDashboard.windows[String(econDays)].package?.pricing_ready?'Данные готовы к проверке владельцем':'Собираем реальные данные'}</strong></span><small>{humanizeBusinessText(ownerDashboard.windows[String(econDays)].package?.reason,'BORIS продолжает собирать фактические данные')}</small></div><div className="bp-econ-card bp-econ-wide"><b>Источники → звонок → продажа</b>{(ownerDashboard.windows[String(econDays)].sources?.source_summary||ownerDashboard.windows[String(econDays)].sources?.sources||[]).slice(0,8).map((x:any)=><span key={(x.source||'')+(x.source_ref||'')}>{humanizeBusinessText(x.source,'Источник')}{x.source_ref?' · '+x.source_ref:''}: <strong>{x.calls} звонков · {x.hot} горячих · {x.won_deals} продаж · {Number(x.won_revenue_rub||0).toLocaleString('ru-RU')} ₽</strong>{x.ad_spend_rub!=null?<> · расход <strong>{Number(x.ad_spend_rub).toLocaleString('ru-RU')} ₽</strong></>:null} · окупаемость {x.roi_pct==null?'—':x.roi_pct+'%'}</span>)}<small>Окупаемость остаётся «—», пока к источнику не подключены реальные рекламные расходы. Себестоимость телефонии не подменяет рекламный бюджет.</small></div></>:null}<div className="bp-truth">Продажа учитывается только по реальной CRM-сделке со статусом «успешно». Следующий шаг, горячий лид или замер не подменяют выручку. Расчёт тарифов использует данные только после достаточного накопления фактической статистики.</div></>}</section>}
  {tab==='Подключение'&&<section className="bp-calls"><div className="bp-panel-title"><span><Icon name="plug" size={20}/></span><div><b>Оператор телефонии</b><small>Подключение подтверждается только реальной проверкой состояния оператора без внесения изменений. Тестовый звонок для проверки не выполняется.</small></div></div>{mcnOnboarding?.primary_next_action?.code==='mcn_phone_entitlement_required'?<div className="bp-econ-card bp-econ-wide"><b>MCN уже прислал SIP-параметры</b><span>Для линии ещё нет активного оплаченного Phone-модуля. Если оплата уже подтверждена, внесите фактические коммерческие данные один раз — BORIS активирует Phone и сам продолжит подключение MCN.</span><small>Не отмечайте услугу оплаченной заранее: срок, сумма и подтверждение платежа сохраняются как коммерческое основание активации.</small><div className="bp-report-grid"><label>Подтверждение оплаты / счёт / договор<input value={phoneEntitlementDraft.commercial_ref||''} placeholder="Например: счёт 154 оплачен 08.09.2026" onChange={e=>setPhoneEntitlementDraft({...phoneEntitlementDraft,commercial_ref:e.target.value})}/></label><label>Оплачено до<input type="datetime-local" value={phoneEntitlementDraft.paid_until||''} onChange={e=>setPhoneEntitlementDraft({...phoneEntitlementDraft,paid_until:e.target.value})}/></label><label>Сумма Phone, ₽<input type="number" min="1" step="1" value={phoneEntitlementDraft.price_rub||''} onChange={e=>setPhoneEntitlementDraft({...phoneEntitlementDraft,price_rub:e.target.value})}/></label></div><div className="bp-controls"><button className="bp-primary" disabled={phoneEntitlementSaving||!accountId||!String(phoneEntitlementDraft.commercial_ref||'').trim()||!String(phoneEntitlementDraft.paid_until||'').trim()||Number(phoneEntitlementDraft.price_rub)<=0} onClick={activatePhoneEntitlement}>{phoneEntitlementSaving?'Подтверждаю…':'Подтвердить оплату Phone и продолжить'}</button><button type="button" onClick={()=>{if(typeof window!=='undefined')window.location.href='/dashboard/billing?product=phone'}}>Открыть биллинг</button></div></div>:null}{mcnOnboarding?.primary_next_action?.code==='mcn_phone_account_binding_required'?<div className="bp-econ-card bp-econ-wide"><b>К какому клиенту относится новая линия MCN?</b><span>MCN уже прислал рабочие SIP-параметры, но оплаченный Phone есть у нескольких клиентов. BORIS специально не угадывает аккаунт.</span><small>Выберите клиента один раз. Перед применением BORIS повторно проверит текущее письмо MCN; логин, пароль и номер на экран не выводятся.</small><div className="bp-controls">{Array.isArray(mcnOnboarding?.eligible_phone_accounts)&&mcnOnboarding.eligible_phone_accounts.length?mcnOnboarding.eligible_phone_accounts.map((x:any)=><button key={String(x?.account_id||'')} className="bp-primary" disabled={mcnBindingSaving||!mcnOnboarding?.account_binding_supported} onClick={()=>bindMcnPhoneAccount(String(x?.account_id||''))}>{mcnBindingSaving?'Привязываю…':String(x?.display_name||x?.account_id||'Выбрать аккаунт')}</button>):<span>Список оплаченных Phone-аккаунтов обновляется.</span>}</div></div>:null}{mcnOnboarding?.primary_next_action?.code==='mcn_company_card_send_approval'&&mcnOnboarding?.approval_supported?<div className="bp-econ-card bp-econ-wide"><b>MCN ждёт карточку предприятия</b><span>Карточка уже проверена BORIS и находится в черновиках. При отправке будут переданы банковские и юридические реквизиты.</span><small>После отправки BORIS сам будет проверять ответ MCN и подхватит SIP-параметры, когда появится однозначный Phone-аккаунт.</small><button className="bp-primary" disabled={mcnApprovalSending} onClick={sendMcnCompanyCard}>{mcnApprovalSending?'Отправляю…':'Отправить карточку MCN'}</button></div>:mcnOnboarding?.primary_next_action?.code==='mcn_company_card_sent_waiting_reply'?<div className="bp-note"><b>Карточка MCN уже отправлена.</b> BORIS сам ждёт оформление и SIP-параметры; повторно отправлять документ не нужно.</div>:null}{mcnOnboarding?.owner_action_required&&!['mcn_phone_entitlement_required','mcn_phone_account_binding_required','mcn_company_card_send_approval','mcn_company_card_sent_waiting_reply'].includes(String(mcnOnboarding?.primary_next_action?.code||''))?<div className="bp-econ-card bp-econ-wide"><b>Нужно решение владельца</b><span>{String(mcnOnboarding?.primary_next_action?.text||'BORIS обнаружил внешний блокер, который нельзя безопасно исправить автоматически.')}</span><small>BORIS продолжает мониторинг и не повторяет опасные внешние действия автоматически.</small></div>:null}<div className="bp-provider-cards">{selectableProviders.map((p:any)=><button key={p.key} className={`bp-provider-card ${providerDraft===p.key?'selected':''}`} onClick={()=>chooseProvider(p.key)}><b>{p.name}</b><span>{(p.capabilities||[]).map((x:any)=>humanizeBusinessText(x,'Возможность')).join(' · ')||'Интеграция готовится'}</span><em>{providerDraft===p.key?(p.implemented?'Подключение готово':'Подключение ещё не готово'):p.implemented?'Доступен':'В разработке'}</em></button>)}</div>{providerDraft?<div className="bp-route-grid"><div className="bp-side"><div className="bp-panel-title"><span><Icon name="plug" size={18}/></span><div><b>{selectedProvider?.name||providerDraft}</b><small>{selectedProvider?.implemented?'Введите рабочие доступы. Секреты после сохранения обратно не показываются.':'Оператора можно выбрать, но подключение останется в ожидании готовности.'}</small></div></div>{providerDraft==='zadarma'?<><label>Ключ пользователя / ключ API<input type="password" autoComplete="new-password" value={providerSecrets.user_key||''} placeholder={providerCfg?.has_credentials&&providerCfg?.provider==='zadarma'?'Ключ уже сохранён · оставьте пустым, чтобы не менять':'Zadarma user_key'} onChange={e=>setProviderSecrets({...providerSecrets,user_key:e.target.value})}/></label><label>Секретный ключ<input type="password" autoComplete="new-password" value={providerSecrets.secret_key||''} placeholder={providerCfg?.has_credentials&&providerCfg?.provider==='zadarma'?'Секрет уже сохранён · оставьте пустым, чтобы не менять':'Zadarma secret_key'} onChange={e=>setProviderSecrets({...providerSecrets,secret_key:e.target.value})}/></label><label>Номер для обратного звонка<input value={providerPublic.callback_from||''} placeholder="SIP / внутренний номер" onChange={e=>setProviderPublic({...providerPublic,callback_from:e.target.value})}/></label><label>SIP, если используется<input value={providerPublic.sip||''} placeholder="100" onChange={e=>setProviderPublic({...providerPublic,sip:e.target.value})}/></label><label>Исходящий номер<input value={providerPublic.outbound_number||''} placeholder="+7…" onChange={e=>setProviderPublic({...providerPublic,outbound_number:e.target.value})}/></label></>:providerDraft==='novofon'?<><label>Ключ пользователя / ключ API<input type="password" autoComplete="new-password" value={providerSecrets.user_key||''} placeholder={providerCfg?.has_credentials&&providerCfg?.provider==='novofon'?'Ключ уже сохранён · оставьте пустым, чтобы не менять':'Novofon user_key'} onChange={e=>setProviderSecrets({...providerSecrets,user_key:e.target.value})}/></label><label>Секретный ключ<input type="password" autoComplete="new-password" value={providerSecrets.secret_key||''} placeholder={providerCfg?.has_credentials&&providerCfg?.provider==='novofon'?'Секрет уже сохранён · оставьте пустым, чтобы не менять':'Novofon secret_key'} onChange={e=>setProviderSecrets({...providerSecrets,secret_key:e.target.value})}/></label><label>Номер для обратного звонка<input value={providerPublic.callback_from||''} placeholder="SIP / внутренний номер" onChange={e=>setProviderPublic({...providerPublic,callback_from:e.target.value})}/></label><label>SIP, если используется<input value={providerPublic.sip||''} placeholder="100" onChange={e=>setProviderPublic({...providerPublic,sip:e.target.value})}/></label><label>Исходящий номер<input value={providerPublic.outbound_number||''} placeholder="+7…" onChange={e=>setProviderPublic({...providerPublic,outbound_number:e.target.value})}/></label></>:providerDraft==='mango'?<><label>Ключ API виртуальной АТС<input type="password" autoComplete="new-password" value={providerSecrets.vpbx_api_key||''} placeholder={providerCfg?.has_credentials&&providerCfg?.provider==='mango'?'Ключ уже сохранён · оставьте пустым, чтобы не менять':'MANGO vpbx_api_key'} onChange={e=>setProviderSecrets({...providerSecrets,vpbx_api_key:e.target.value})}/></label><label>Секрет API виртуальной АТС<input type="password" autoComplete="new-password" value={providerSecrets.vpbx_api_salt||''} placeholder={providerCfg?.has_credentials&&providerCfg?.provider==='mango'?'Salt уже сохранён · оставьте пустым, чтобы не менять':'MANGO vpbx_api_salt'} onChange={e=>setProviderSecrets({...providerSecrets,vpbx_api_salt:e.target.value})}/></label><label>Добавочный сотрудника<input value={providerPublic.extension||''} placeholder="101" onChange={e=>setProviderPublic({...providerPublic,extension:e.target.value})}/></label><label>SIP / номер сотрудника<input value={providerPublic.sip||providerPublic.from_number||''} placeholder="SIP или номер" onChange={e=>setProviderPublic({...providerPublic,sip:e.target.value})}/></label><label>Линия / исходящий номер<input value={providerPublic.line_number||providerPublic.outbound_number||''} placeholder="Виртуальный номер" onChange={e=>setProviderPublic({...providerPublic,line_number:e.target.value})}/></label><small className="bp-truth">Для событий MANGO настройте события на BORIS: /api/telephony/public/native/mango/{accountId}/events/call, /events/summary и /events/recording. Подпись каждого события проверяется по вашим Ключ API виртуальной АТС + salt.</small></>:providerDraft==='uis'?<><label>Портал<select value={providerPublic.portal||'uis'} onChange={e=>setProviderPublic({...providerPublic,portal:e.target.value})}><option value="uis">UIS</option><option value="comagic">CoMagic</option></select></label><label>Постоянный ключ доступа<input type="password" autoComplete="new-password" value={providerSecrets.access_token||''} placeholder={providerCfg?.has_credentials&&providerCfg?.provider==='uis'?'Ключ уже сохранён · оставьте пустым, чтобы не менять':'Рекомендуемый способ'} onChange={e=>setProviderSecrets({...providerSecrets,access_token:e.target.value})}/></label><small className="bp-truth">Либо используйте постоянный ключ выше, либо логин и пароль ниже.</small><label>Логин<input autoComplete="username" value={providerSecrets.login||''} placeholder="UIS login" onChange={e=>setProviderSecrets({...providerSecrets,login:e.target.value})}/></label><label>Пароль<input type="password" autoComplete="new-password" value={providerSecrets.password||''} placeholder={providerCfg?.has_credentials&&providerCfg?.provider==='uis'?'Пароль уже сохранён · оставьте пустым, чтобы не менять':'UIS password'} onChange={e=>setProviderSecrets({...providerSecrets,password:e.target.value})}/></label><label>ID сотрудника<input value={providerPublic.employee_id??''} placeholder="25" inputMode="numeric" onChange={e=>setProviderPublic({...providerPublic,employee_id:e.target.value})}/></label><label>Телефон сотрудника<input value={providerPublic.employee_phone||''} placeholder="+7…" onChange={e=>setProviderPublic({...providerPublic,employee_phone:e.target.value})}/></label><label>Виртуальный исходящий номер<input value={providerPublic.virtual_phone_number||providerPublic.outbound_number||''} placeholder="+7…" onChange={e=>setProviderPublic({...providerPublic,virtual_phone_number:e.target.value})}/></label><label>Секрет уведомлений BORIS<input type="password" autoComplete="new-password" value={providerWebhookSecret} placeholder={providerCfg?.webhook_ready&&providerCfg?.provider==='uis'?'Секрет уже сохранён · оставьте пустым, чтобы не менять':'Придумайте длинный случайный секрет'} onChange={e=>setProviderWebhookSecret(e.target.value)}/></label><small className="bp-truth">Для HTTP-уведомлений UIS добавьте в JSON поле boris_secret с этим значением. Адрес BORIS: /api/telephony/public/native/uis/{accountId}</small></>:providerDraft==='mcn'?<><small className="bp-truth"><b>MCN — только оператор связи.</b> Номер, SIP-транк и минуты берём у MCN. Виртуальная АТС, маршрутизация, веб-телефон, запись, коллтрекинг, CRM и ИИ остаются внутри BORIS.</small><div className="bp-truth"><b>Что нужно от владельца один раз:</b> Логин SIP, Пароль SIP и номер MCN. Сервер <b>sip.mcn.ru</b>, IP-адреса для сетевого фильтра и Asterisk BORIS настроит сам. Пароль в MCN: <b>Телефония → SIP-аккаунты → нужная запись → Редактировать → Отправить настройки</b>. API-токен для обычного подключения не нужен. <a href="https://handbook.mcn.ru/ru/telefoniya/nastroyka/kak-poluchit-parol-nastroyki-k-uchetnoy-zapisi-sip--31f02738-6fee-472e-a64b-01123b73f0ce/" target="_blank" rel="noreferrer">Открыть инструкцию MCN</a></div><label>Вставить настройки MCN целиком<textarea value={mcnSettingsText} placeholder={"Например:\nСервер SIP: sip.mcn.ru\nЛогин SIP: ...\nПароль SIP: ...\nНомер MCN: +7..."} onChange={e=>setMcnSettingsText(e.target.value)}/></label><div className="bp-controls"><button type="button" disabled={!mcnSettingsText.trim()||mcnSaving} onClick={()=>importMcnSettings(false)}>Распознать и заполнить</button><button type="button" className="bp-primary" disabled={!mcnSettingsText.trim()||mcnSaving} onClick={()=>importMcnSettings(true)}>{mcnSaving?'Подключаю…':'Распознать, сохранить и проверить'}</button></div><small className="bp-truth">Разбор выполняется прямо в браузере без ИИ и отдельного внешнего сервиса разбора. Если все обязательные поля распознаны, BORIS может сразу сохранить MCN и запустить проверку. Если чего-то не хватает — ничего автоматически не сохраняется. Исходный текст с паролем после распознавания очищается.</small><label>Тип подключения<select value={mcnDraft.auth_mode||'registration'} onChange={e=>setMcnDraft({...mcnDraft,auth_mode:e.target.value})}><option value="registration">SIP-регистрация: логин + пароль</option><option value="ip">По IP-адресам</option></select></label><label>Сервер регистрации SIP<input value={mcnDraft.registrar||''} placeholder="Сервер из данных подключения MCN" onChange={e=>setMcnDraft({...mcnDraft,registrar:e.target.value})}/></label><label>Промежуточный сервер, если указан MCN<input value={mcnDraft.outbound_proxy||''} placeholder="Оставьте пустым, если совпадает с сервером SIP" onChange={e=>setMcnDraft({...mcnDraft,outbound_proxy:e.target.value})}/></label>{mcnDraft.auth_mode!=='ip'?<><label>Логин SIP<input type="password" autoComplete="new-password" value={mcnDraft.username||''} placeholder={mcnSetup?.trunks?.[0]?.has_username?'Логин уже сохранён · пусто = не менять':'Логин SIP-транка MCN'} onChange={e=>setMcnDraft({...mcnDraft,username:e.target.value})}/></label><label>Пароль SIP<input type="password" autoComplete="new-password" value={mcnDraft.password||''} placeholder={mcnSetup?.trunks?.[0]?.has_password?'Пароль уже сохранён · пусто = не менять':'Пароль SIP-транка MCN'} onChange={e=>setMcnDraft({...mcnDraft,password:e.target.value})}/></label></>:null}<label>IP-адреса MCN{mcnDraft.auth_mode==='ip'?' · обязательно для IP-транка':' · необязательно, BORIS определит по SIP registrar'}<input value={mcnDraft.source_ips||''} placeholder={mcnDraft.auth_mode==='ip'?'Например 1.2.3.4, 5.6.7.8/32':'Оставьте пустым для автоопределения'} onChange={e=>setMcnDraft({...mcnDraft,source_ips:e.target.value})}/></label><label>Ваш номер MCN<input value={mcnDraft.number||''} inputMode="tel" placeholder="+7…" onChange={e=>setMcnDraft({...mcnDraft,number:e.target.value})}/></label><label>Регион номера, необязательно<input value={mcnDraft.region||''} placeholder="Москва / Санкт-Петербург / другой" onChange={e=>setMcnDraft({...mcnDraft,region:e.target.value})}/></label><label className="bp-switchrow"><span><b>Использовать номер для исходящих</b><small>BORIS разрешит этот исходящий номер только после сохранения номера.</small></span><input type="checkbox" checked={mcnDraft.outbound_cli_enabled!==false} onChange={e=>setMcnDraft({...mcnDraft,outbound_cli_enabled:e.target.checked})}/></label><small className="bp-truth">BORIS сам создаст конфигурацию Asterisk, применит её только в безопасный момент и затем будет проверять SIP без ручных перезапусков.</small></>:providerDraft==='telphin'?<><small className="bp-truth"><b>1. API Телфин</b> — нужен для проверки без изменений, обратных звонков, записей и REST-операций. Секреты хранятся только на backend.</small><label>Идентификатор приложения (client_id)<input type="password" autoComplete="new-password" value={providerSecrets.client_id||''} placeholder={providerCfg?.has_credentials&&providerCfg?.provider==='telphin'?'Client ID уже сохранён · оставьте пустым, чтобы не менять':'Telphin trusted app client_id'} onChange={e=>setProviderSecrets({...providerSecrets,client_id:e.target.value})}/></label><label>Секрет приложения (client_secret)<input type="password" autoComplete="new-password" value={providerSecrets.client_secret||''} placeholder={providerCfg?.has_credentials&&providerCfg?.provider==='telphin'?'Секрет уже сохранён · оставьте пустым, чтобы не менять':'Telphin trusted app client_secret'} onChange={e=>setProviderSecrets({...providerSecrets,client_secret:e.target.value})}/></label><label>ID добавочного<input value={providerPublic.extension_id||''} placeholder="Например 12345" inputMode="numeric" onChange={e=>setProviderPublic({...providerPublic,extension_id:e.target.value.replace(/\D/g,'')})}/></label><label>Номер / добавочный источника<input value={providerPublic.src_num||''} placeholder="Добавочный или номер сотрудника" onChange={e=>setProviderPublic({...providerPublic,src_num:e.target.value})}/></label><small className="bp-truth"><b>2. SIP-линия для реального звука</b> — отдельный логин и пароль линии Телфин. Они не заменяют API-ключи. BORIS регистрирует линию в Asterisk и сам контролирует её состояние.</small><label>Логин SIP / линия<input type="password" autoComplete="new-password" value={providerSecrets.sip_line||''} placeholder={providerCfg?.provider==='telphin'&&providerCfg?.sip_trunk?.enabled?'SIP-линия уже сохранена · оставьте пустым, чтобы не менять':'Логин SIP-линии Телфин'} onChange={e=>setProviderSecrets({...providerSecrets,sip_line:e.target.value})}/></label><label>Пароль SIP<input type="password" autoComplete="new-password" value={providerSecrets.sip_password||''} placeholder={providerCfg?.provider==='telphin'&&providerCfg?.sip_trunk?.enabled?'SIP-пароль уже сохранён · оставьте пустым, чтобы не менять':'Пароль SIP-линии'} onChange={e=>setProviderSecrets({...providerSecrets,sip_password:e.target.value})}/></label><label>Сервер регистрации<select value={providerPublic.sip_registrar||'sip.telphin.com'} onChange={e=>setProviderPublic({...providerPublic,sip_registrar:e.target.value})}><option value="sip.telphin.com">sip.telphin.com</option><option value="vip1.sip.telphin.com">vip1.sip.telphin.com</option><option value="vip2.sip.telphin.com">vip2.sip.telphin.com</option><option value="vip3.sip.telphin.com">vip3.sip.telphin.com</option></select></label><label>Исходящий номер для SIP<input value={providerPublic.sip_outbound_number||''} placeholder="+7…" onChange={e=>setProviderPublic({...providerPublic,sip_outbound_number:e.target.value})}/></label><label>Использовать SIP для звука<select value={providerPublic.sip_enabled===false?'off':'on'} onChange={e=>setProviderPublic({...providerPublic,sip_enabled:e.target.value==='on'})}><option value="on">Да</option><option value="off">Нет</option></select></label><small className="bp-truth">SIP считается готовым только после фактической регистрации линии в Asterisk. Если применение пришлось отложить из-за активного звонка, BORIS применит его сам после освобождения линии.</small></>:<div className="bp-empty">Рабочее подключение для {selectedProvider?.name||providerDraft} ещё не реализовано. BORIS не будет показывать фиктивный статус «подключено».</div>}<div className="bp-controls"><button className="bp-primary" disabled={providerDraft==='mcn'?mcnSaving:providerSaving} onClick={()=>providerDraft==='mcn'?saveMcnSetup():saveAndVerifyProvider()}>{providerDraft==='mcn'?(mcnSaving?'Применяю…':'Сохранить MCN и проверить'):(providerSaving?'Проверяю…':'Сохранить и проверить')}</button>{providerDraft==='mcn'&&mcnSetup?.trunks?.length?<button disabled={mcnSaving} onClick={async()=>{setMcnSaving(true);try{await apiPost('/api/telephony/provider-config/verify',{account_id:accountId});const r=await apiGet(`/api/mcn/setup?account_id=${encodeURIComponent(accountId)}`);setMcnSetup(r);setNote(r?.readiness?.ready?'Линия MCN подтверждена.':'BORIS продолжает проверять SIP автоматически.')}catch{setNote('Не удалось выполнить проверку линии MCN')}finally{setMcnSaving(false)}}}>Проверить линию</button>:providerDraft!=='mcn'&&providerCfg?.has_credentials&&providerCfg?.provider===providerDraft?<button disabled={providerSaving} onClick={verifyProvider}>Повторить проверки состояния</button>:null}</div></div><div className="bp-side"><div className="bp-panel-title"><span><Icon name="chart" size={18}/></span><div><b>Состояние подключения</b><small>Фактическое состояние сервера</small></div></div><div className="bp-provider"><span>Оператор</span><em>{providerDraft||'—'}</em><span>Подключение</span><em>{selectedProvider?.implemented?'готов':'ожидается'}</em>{providerDraft==='mcn'?<><span>SIP-транк</span><em>{mcnSetup?.trunks?.length?humanizeBusinessText(mcnSetup?.trunks?.[0]?.status,'сохранён'):'не настроен'}</em><span>Номер MCN</span><em>{mcnSetup?.dids?.[0]?.number_e164||'не добавлен'}</em><span>Транспорт</span><em>{mcnSetup?.transport?.ready?'онлайн · SIP подтверждён':mcnSetup?.transport?.trunks?.[0]?.live_status==='registration_rejected'?'отклонён · проверьте логин/пароль':mcnSetup?.transport?.trunks?.[0]?.live_status==='registration_unregistered'?'не зарегистрирован · BORIS повторяет':mcnSetup?.transport?.trunks?.[0]?.live_status==='registration_pending'?'регистрация выполняется':mcnSetup?.transport?.trunks?.[0]?.live_status==='registration_missing'?'SIP ещё не применён':mcnSetup?.trunks?.length?'проверяется':'ожидает данных'}</em><span>Готовность</span><em>{mcnSetup?.readiness?.ready?'готово':mcnSetup?.transport?.trunks?.[0]?.live_status==='registration_rejected'?'нужны верные данные MCN':Array.isArray(mcnSetup?.readiness?.blockers)&&mcnSetup.readiness.blockers.includes('mcn_active_did_missing')?'добавьте номер MCN':'BORIS проверяет'}</em><span>Прогресс MCN</span><em>{Number(mcnSetup?.readiness?.steps_completed||0)} из {Number(mcnSetup?.readiness?.steps_total||3)} шагов</em><span>Что дальше</span><em>{humanizeBusinessText(mcnSetup?.readiness?.primary_next_action?.text,'BORIS определяет следующий шаг')}</em></>:<><span>Доступы</span><em>{providerCfg?.provider===providerDraft&&providerCfg?.has_credentials?'сохранены':'не подтверждены'}</em><span>Проверка API</span><em>{data?.provider===providerDraft?humanizeBusinessText(data?.provider_health?.last_health_status||data?.provider_state,'Состояние уточняется'):'ещё не проверялся'}</em></>}{providerDraft==='telphin'?<><span>SIP-линия</span><em>{humanizeBusinessText(data?.telphin_sip?.status||providerCfg?.sip_trunk?.status,'не настроена')}</em><span>Звук BORIS</span><em>{data?.telphin_sip?.ready?'готов · SIP зарегистрирован':data?.telphin_sip?.status==='apply_deferred'?'применится после текущего звонка':'ожидает регистрации SIP'}</em></>:null}<span>API подключение</span><em>{data?.provider===providerDraft&&data?.provider_verified?'подтверждено':'не подтверждено'}</em></div><small className="bp-truth">Ключи шифруются на сервере. На экране показывается только признак их наличия, без самих секретов.</small></div></div>:<div className="bp-empty">Выберите оператора выше.</div>}{note?<div className="bp-note">{note}</div>:null}<div className="bp-truth">{providerDraft==='mcn'?'Для BORIS основной целевой контур: MCN даёт номер, SIP-транк и минуты. Собственная Asterisk BORIS отвечает за ВАТС, веб-телефон, запись, маршрутизацию, коллтрекинг, CRM и ИИ. Линия считается рабочей только после фактической проверки SIP; потерю транспорта BORIS обнаруживает и перепроверяет сам.':'Другие операторы остаются доступными как отдельные интеграции. Их подключение считается рабочим только после фактической проверки состояния, без демонстрационного статуса.'}</div></section>}
  {loading?<div className="bp-loading">Обновляю данные…</div>:null}
 </main>
